export type MergeOptions = {
	source: string,
	noFastForward: boolean,
	squash: boolean,
	message: string | null,
};

/**
 *  A conflicted file was resolved in its own window; the main one refreshes on it.
 *  The page emits it itself, like `RevealCommit`.
 */
