export type Submodule = {
	name: string,
	path: string,
	url: string,
	recorded: string,
	checkedOut: string | null,
	state: SubmoduleState,
	/**
	 *  The branch it is on, when it is on one. A submodule is usually detached, and then
	 *  the row has to name the commit instead (R-110).
	 */
	branch: string | null,
	/**  First line of the commit it sits on, for the row that has no branch to show. */
	subject: string | null,
	/**
	 *  Whether it holds submodules of its own. Answered here so the tree can decide
	 *  before drawing whether the row opens at all (doc/12-risks.md, R-148).
	 */
	nested: boolean,
	/**
	 *  Commits on each side of the merge base, for the tooltip; zero unless ahead,
	 *  behind or diverged.
	 */
	ahead: number,
	behind: number,
	/**  What the submodule's own repository is in the middle of; `None` until it is checked out. */
	repoState: RepoState | null,
	/**
	 *  `submodule.<name>.update` as configured: `rebase`, `merge`, `none` or `!command`;
	 *  `None` for the default checkout.
	 */
	update: string | null,
	/**  A `./` or `../` URL resolved against the parent's remote, as git clones it. */
	resolvedUrl: string | null,
};

/**
 *  What a submodule row stands for. `git add` records only the commit (`new_commits`);
 *  `modified` and `untracked` are edits inside the submodule that no parent commit can hold.
 */
export type SubmoduleChange = {
	newCommits: boolean,
	modified: boolean,
	untracked: boolean,
};

export type SubmoduleOp = "initialize" | "synchronize" | 
/**  Back to the commit the parent records. git refuses to overwrite local changes. */
"reset" | 
/**  `submodule.<name>.active = false`: recursive commands skip it, the files stay. */
"deactivate" | "deinit" | 
/**  Out of the index and `.gitmodules`; the files stay behind as an untracked folder. */
"unregister";

export type SubmoduleState = "notInitialised" | "inSync" | 
/**  New commits on top of the recorded one: commit the pointer in the parent. */
"ahead" | 
/**  On an ancestor of the recorded commit: `git submodule update`. */
"behind" | 
/**  Neither contains the other; only a person can decide which side wins. */
"diverged" | 
/**  The recorded commit is not in the submodule, so where it stands cannot be told. */
"unknown" | 
/**  Checked out, and not looked into: the outline of a repository not on screen (R-352). */
"unread" | 
/**  Listed in `.gitmodules`, with no gitlink in HEAD or the index to compare with. */
"unrecorded";

export type SubtreeOp = { kind: "add"; prefix: string; repository: string; reference: string; squash: boolean } | 
/**  `git subtree pull` from `repository`, or `git subtree merge` of a local commit. */
{ kind: "merge"; prefix: string; repository: string | null; reference: string; squash: boolean } | 
/**  The folder's own history as a new branch. */
{ kind: "split"; prefix: string; branch: string; rejoin: boolean } | 
/**  The folder's contents replaced by `reference`'s tree, staged for the next commit. */
{ kind: "reset"; prefix: string; reference: string } | { kind: "push"; prefix: string; repository: string; reference: string };

